here = os.path.dirname(os.path.abspath(__file__))
def esc(s):
    s = s.replace("\\n", "\n")   # im Skript als \\n notierte Zeilenumbrueche
    return s.replace("\\", "\\\\").replace("\n", "\\n").replace("\t", "\\t")
head = "# Grandia II Modifier, Sprachdatei. Format: deutscher Text TAB Uebersetzung. {0} usw. = Platzhalter.\n# Diese Datei darf korrigiert werden: als sprachen\\{0}.txt neben G2Modifier.exe ablegen, sie hat dann Vorrang.\n"
for i, code in enumerate(["en", "fr"]):
    with open(os.path.join(here, code + ".txt"), "w", encoding="utf-8", newline="\n") as f:
        f.write(head.replace("{0}", code))
        for k, v in T.items(): f.write(esc(k) + "\t" + esc(v[i]) + "\n")
        if code == "fr":
            f.write("# Bezeichnungslisten aus G2DataGUI (englisch -> franzoesisch)\n")
            for k, v in G.items(): f.write(esc(k) + "\t" + esc(v[1]) + "\n")
with open(os.path.join(here, "de.txt"), "w", encoding="utf-8", newline="\n") as f:
    f.write(head.replace("{0}", "de") + "# Nur die englischen Bezeichnungslisten aus G2DataGUI -> deutsch\n")
    for k, v in G.items(): f.write(esc(k) + "\t" + esc(v[0]) + "\n")
